"""Plain-language explanation of one place and one night, generated by muse-spark when the
user opens that place in the app (GET /map/{point_id}/explain).

One base explanation is generated per place and night, in Spanish. Other languages (en, ay,
qu) are translations of that same text by Muse, so every language says the same thing and a
new language costs only a short translation call.

The text is generated on demand from the current processed data: when new nights arrive or
a night is reprocessed, the facts change and a new explanation is generated. Identical facts
reuse the stored text (cost control, CLAUDE.md rule 21). Muse never sees the place name, the
date or any observed outcome: it writes {place} and {night} placeholders, which are filled in
afterwards, and it only rephrases numbers it was given. Actions and information sources come
from fixed catalogs (Muse picks ids, it never writes a web address). Any failure falls back to
a deterministic template. Languages: es, en, ay, qu (Aymara and Quechua are generated by Muse;
the template for them is Spanish).
"""

from __future__ import annotations

import datetime as dt
import hashlib
import json
import logging
import re
from dataclasses import dataclass
from pathlib import Path

from sqlalchemy import select
from sqlalchemy.orm import Session

from ..models import Explanation
from ..providers.base import CellRecord
from .drivers import group_drivers
from .explain import ACTIONS, BANNED, NUMBER, Explainer, _strip_fences, content_language, empty_reply_reason
from .risk import LEVEL_ORDER

log = logging.getLogger("frostwatch.place_explain")

PROMPT_VERSION = "place-explain-v2"
PROMPT_FILE = Path(__file__).resolve().parents[1] / "prompts" / "place_explain_v1.txt"
TRANSLATE_VERSION = "place-translate-v1"
TRANSLATE_FILE = Path(__file__).resolve().parents[1] / "prompts" / "place_translate_v1.txt"
BASE_LANGUAGE = "es"
TEXT_KEYS = ("headline", "what_happened", "what_next")
LANGUAGES = ("es", "en", "ay", "qu")
URL = re.compile(r"https?://|www\.|\.(com|org|bo|eu)\b", re.IGNORECASE)
# Muse calls (explanations and translations) per user per hour; stored texts do not count.
USER_CALLS_PER_HOUR = 30
RETRY_LATER = ("truncated", "empty_reply")

LEVEL_WORDS = {
    "es": {"low": "bajo", "moderate": "moderado", "high": "alto", "very_high": "muy alto"},
    "en": {"low": "low", "moderate": "moderate", "high": "high", "very_high": "very high"},
}
MONTHS = {
    "es": ["enero", "febrero", "marzo", "abril", "mayo", "junio", "julio", "agosto", "septiembre", "octubre",
           "noviembre", "diciembre"],
    "en": ["January", "February", "March", "April", "May", "June", "July", "August", "September", "October",
           "November", "December"],
}

# Official or widely used sources, checked to respond on 2026-11-04.
SOURCES: list[dict] = [
    {"id": "senamhi", "name": "SENAMHI Bolivia", "url": "https://senamhi.gob.bo",
     "about": {"es": "Pronóstico del tiempo y avisos oficiales de heladas.",
               "en": "Official weather forecast and frost warnings."}},
    {"id": "defensa_civil", "name": "Viceministerio de Defensa Civil", "url": "https://defensacivil.gob.bo",
     "about": {"es": "Alertas y ayuda ante emergencias climáticas.",
               "en": "Alerts and help in weather emergencies."}},
    {"id": "radio_san_gabriel", "name": "Radio San Gabriel", "url": "https://radiosangabriel.org.bo",
     "about": {"es": "Radio en aymara y castellano con noticias del Altiplano.",
               "en": "Radio in Aymara and Spanish with Altiplano news."}},
    {"id": "abi", "name": "ABI, Agencia Boliviana de Información", "url": "https://abi.bo",
     "about": {"es": "Noticias nacionales, incluidas heladas y clima.",
               "en": "National news, including frost and weather."}},
    {"id": "copernicus", "name": "Copernicus Climate Data Store", "url": "https://cds.climate.copernicus.eu",
     "about": {"es": "Origen de los datos de reanálisis que usa esta app.",
               "en": "Source of the reanalysis data this app uses."}},
]
TEMPLATE_SOURCES = ["senamhi", "defensa_civil", "radio_san_gabriel"]

# Only plain evening conditions are shared (no pressure or radiation terms).
CONDITIONS = {
    "t2m_c": ("air temperature at 18:00, °C", 1),
    "rh_pct": ("relative humidity at 18:00, %", 0),
    "wind_ms": ("wind at 18:00, m/s", 1),
}


@dataclass
class PlaceFacts:
    language: str
    profile: str
    probability_pct: int
    level: str
    conditions_1800: dict[str, float]
    drivers: list[dict]
    previous_night: dict | None
    next_night: dict | None
    model_version: str
    cutoff_local: str = "18:00"

    def public(self) -> dict:
        d = dict(self.__dict__)
        d.pop("model_version")
        d["place"] = "{place}"
        d["night"] = "{night}"
        return d


def _night_summary(rec: CellRecord | None) -> dict | None:
    if rec is None:
        return None
    return {"probability_pct": round(rec.probability * 100), "level": rec.level}


def build_place_facts(rec: CellRecord, previous: CellRecord | None, following: CellRecord | None,
                      profile: str, language: str) -> PlaceFacts:
    groups = group_drivers(rec.top_drivers)
    label_lang = "en" if language == "en" else "es"
    conditions = {}
    for key, (label, digits) in CONDITIONS.items():
        if key in rec.conditions_1800:
            value = round(rec.conditions_1800[key], digits)
            conditions[label] = int(value) if digits == 0 else value
    return PlaceFacts(
        language=language, profile=profile, probability_pct=round(rec.probability * 100), level=rec.level,
        conditions_1800=conditions,
        drivers=[{"label": g.label_es if label_lang == "es" else g.label_en,
                  "effect": "raises risk" if g.effect == "up" else "lowers risk"} for g in groups[:4]],
        previous_night=_night_summary(previous), next_night=_night_summary(following),
        model_version=rec.model_version)


def catalog_for(facts: PlaceFacts) -> dict:
    lang = content_language(facts.language)
    lvl = max(LEVEL_ORDER[facts.level], LEVEL_ORDER["moderate"])
    actions = [{"id": i, "text": t[lang]} for i, min_lvl, t in ACTIONS[facts.profile] if LEVEL_ORDER[min_lvl] <= lvl]
    sources = [{"id": s["id"], "name": s["name"], "about": s["about"][lang]} for s in SOURCES]
    return {"actions": actions, "sources": sources}


def allowed_numbers(facts: PlaceFacts) -> set[float]:
    nums: set[float] = {facts.probability_pct, 18, 0}
    for value in facts.conditions_1800.values():
        nums |= {float(value), float(round(value))}
    for other in (facts.previous_night, facts.next_night):
        if other:
            nums.add(other["probability_pct"])
    return {float(n) for n in nums}


def verify(payload: dict, facts: PlaceFacts, catalog: dict) -> str | None:
    """None when acceptable, else the reason."""
    keys = {"headline", "what_happened", "what_next", "actions", "sources"}
    if not isinstance(payload, dict) or set(payload) != keys:
        return "schema"
    texts = [payload["headline"], payload["what_happened"], payload["what_next"]]
    if not all(isinstance(t, str) and t.strip() for t in texts) or len(payload["headline"]) > 120:
        return "schema"
    for key, field_name, ids in (("actions", "text", {a["id"] for a in catalog["actions"]}),
                                 ("sources", "why", {s["id"] for s in catalog["sources"]})):
        items = payload[key]
        if not isinstance(items, list) or not items:
            return "schema"
        for it in items:
            if not (isinstance(it, dict) and it.get("id") in ids and isinstance(it.get(field_name), str)
                    and it[field_name].strip()):
                return f"{key}_not_in_catalog"
        texts += [it[field_name] for it in items]
    allowed = allowed_numbers(facts)
    for text in texts:
        if URL.search(text):
            return "url_in_text"
        for raw in NUMBER.findall(text):
            if float(raw.replace(",", ".")) not in allowed:
                return "number_not_in_facts"
    if BANNED.search(" ".join(texts)):
        return "banned_phrase"
    return None


def template(facts: PlaceFacts) -> dict:
    """Deterministic fallback (Spanish for es, ay and qu; English for en)."""
    lang = content_language(facts.language)
    words = LEVEL_WORDS[lang]
    up = [d["label"].lower() for d in facts.drivers if d["effect"] == "raises risk"][:2]
    down = [d["label"].lower() for d in facts.drivers if d["effect"] == "lowers risk"][:2]
    nxt = facts.next_night
    if lang == "es":
        happened = [f"La noche del {{night}} el riesgo de helada en {{place}} fue {words[facts.level]} "
                    f"({facts.probability_pct}%)."]
        if up:
            happened.append(f"Lo que más subió el riesgo esa tarde: {', '.join(up)}.")
        if down:
            happened.append(f"Lo que lo bajó: {', '.join(down)}.")
        nxt_text = (f"La noche siguiente el riesgo fue {words[nxt['level']]} ({nxt['probability_pct']}%)." if nxt else
                    "Todavía no hay una noche más nueva procesada. Revise el pronóstico oficial de SENAMHI.")
        headline = f"Helada: riesgo {words[facts.level]} en {{place}}"
    else:
        happened = [f"On the night of {{night}} the frost risk in {{place}} was {words[facts.level]} "
                    f"({facts.probability_pct}%)."]
        if up:
            happened.append(f"What raised the risk most that evening: {', '.join(up)}.")
        if down:
            happened.append(f"What lowered it: {', '.join(down)}.")
        nxt_text = (f"The following night the risk was {words[nxt['level']]} ({nxt['probability_pct']}%)." if nxt else
                    "There is no newer processed night yet. Check the official SENAMHI forecast.")
        headline = f"Frost: {words[facts.level]} risk in {{place}}"
    catalog = catalog_for(facts)
    by_id = {s["id"]: s for s in catalog["sources"]}
    return {"headline": headline, "what_happened": " ".join(happened), "what_next": nxt_text,
            "actions": [{"id": a["id"], "text": a["text"]} for a in catalog["actions"][:3]],
            "sources": [{"id": i, "why": by_id[i]["about"]} for i in TEMPLATE_SOURCES]}


def readable_date(night: dt.date, language: str) -> str:
    lang = content_language(language)
    month = MONTHS[lang][night.month - 1]
    return f"{night.day} de {month} de {night.year}" if lang == "es" else f"{night.day} {month} {night.year}"


def fill(text: str, place: str, night_text: str) -> str:
    return text.replace("{place}", place).replace("{night}", night_text)


def facts_key(rec: CellRecord, facts: PlaceFacts, engine: str) -> str:
    blob = json.dumps({"cell": rec.point_id, "night": rec.night_date.isoformat(), "facts": facts.__dict__,
                       "prompt": PROMPT_VERSION, "engine": engine}, sort_keys=True, ensure_ascii=False)
    return hashlib.sha256(blob.encode()).hexdigest()


def translation_key(base_key: str, language: str) -> str:
    return hashlib.sha256(f"{base_key}:{language}:{TRANSLATE_VERSION}".encode()).hexdigest()


def source_texts(payload: dict) -> dict:
    """The texts of a base explanation, without ids, as sent for translation."""
    return {**{k: payload[k] for k in TEXT_KEYS}, "actions": [a["text"] for a in payload["actions"]],
            "sources": [s["why"] for s in payload["sources"]]}


def verify_translation(texts: dict, base: dict, facts: PlaceFacts) -> str | None:
    """None when the translation keeps the structure, placeholders and numbers of the base."""
    src = source_texts(base)
    if not isinstance(texts, dict) or set(texts) != set(src):
        return "schema"
    for key in TEXT_KEYS:
        if not isinstance(texts[key], str) or not texts[key].strip():
            return "schema"
    for key in ("actions", "sources"):
        items = texts[key]
        if not isinstance(items, list) or len(items) != len(src[key]) or not all(
                isinstance(t, str) and t.strip() for t in items):
            return "schema"
    allowed = allowed_numbers(facts)
    pairs = [(texts[k], src[k]) for k in TEXT_KEYS]
    pairs += list(zip(texts["actions"], src["actions"], strict=True)) + list(zip(texts["sources"], src["sources"], strict=True))
    for new, old in pairs:
        if URL.search(new):
            return "url_in_text"
        for token in ("{place}", "{night}"):
            if token in old and token not in new:
                return "placeholder_lost"
        for raw in NUMBER.findall(new):
            if float(raw.replace(",", ".")) not in allowed:
                return "number_not_in_facts"
    return None


def apply_translation(base: dict, texts: dict) -> dict:
    """Base payload with translated texts and the same action and source ids."""
    return {**{k: texts[k] for k in TEXT_KEYS},
            "actions": [{"id": a["id"], "text": t} for a, t in zip(base["actions"], texts["actions"], strict=True)],
            "sources": [{"id": s["id"], "why": t} for s, t in zip(base["sources"], texts["sources"], strict=True)]}


def fill_payload(payload: dict, rec: CellRecord, language: str) -> dict:
    """Puts the place name and the readable date in, and resolves source ids to links."""
    night_text = readable_date(rec.night_date, language)
    by_id = {s["id"]: s for s in SOURCES}
    return {
        **{k: fill(payload[k], rec.name, night_text) for k in TEXT_KEYS},
        "actions": [fill(a["text"], rec.name, night_text) for a in payload["actions"]],
        "sources": [{"name": by_id[s["id"]]["name"], "url": by_id[s["id"]]["url"],
                     "why": fill(s["why"], rec.name, night_text)} for s in payload["sources"]],
    }


@dataclass
class PlaceExplanation:
    source: str  # "muse" or "template"
    language: str
    payload: dict
    cached: bool
    translated: bool = False


class PlaceExplainer(Explainer):
    """Reuses the Muse HTTP client and usage log of the alert explainer."""

    def explain_place(self, db: Session, rec: CellRecord, previous: CellRecord | None, following: CellRecord | None,
                      profile: str, language: str, limiter=None, user_key: str = "") -> PlaceExplanation:
        facts = build_place_facts(rec, previous, following, profile, BASE_LANGUAGE)
        key = facts_key(rec, facts, self.engine)
        base, source, cached = self._base(db, facts, key, limiter, user_key)
        if language == BASE_LANGUAGE:
            return PlaceExplanation(source, BASE_LANGUAGE, fill_payload(base, rec, BASE_LANGUAGE), cached)
        if source == "muse":
            texts, hit = self._translation(db, facts, base, key, language, limiter, user_key)
            if texts is not None:
                return PlaceExplanation(source, language, fill_payload(apply_translation(base, texts), rec, language),
                                        cached and hit, translated=True)
        elif language == "en":
            # No Muse base: the English template says the same as the Spanish one.
            en = build_place_facts(rec, previous, following, profile, "en")
            return PlaceExplanation(source, "en", fill_payload(template(en), rec, "en"), cached)
        # Translation not available: the Spanish text, labeled as such.
        return PlaceExplanation(source, BASE_LANGUAGE, fill_payload(base, rec, BASE_LANGUAGE), cached)

    def _limited(self, limiter, user_key: str) -> bool:
        return limiter is not None and not limiter.allow(f"explain:{user_key}", USER_CALLS_PER_HOUR, 3600)

    def _base(self, db: Session, facts: PlaceFacts, key: str, limiter, user_key: str) -> tuple[dict, str, bool]:
        row = db.scalar(select(Explanation).where(Explanation.facts_hash == key))
        if row:
            return row.payload, row.source, True
        catalog = catalog_for(facts)
        payload, reason, cacheable = None, None, True
        if self.settings.muse_mock:
            reason = None
        elif not (self.settings.meta_api_key and self.settings.meta_api_base_url):
            reason, cacheable = "muse_not_configured", False
        elif self._limited(limiter, user_key):
            reason, cacheable = "user_rate_limited", False
        else:
            payload, reason = self._call_place(facts, catalog, key)
            # Network errors and cut or empty replies are retried on the next tap; answers that
            # fail verification are not (the same facts would give the same answer).
            if reason and (reason.startswith("api_error") or reason in RETRY_LATER):
                cacheable = False
        source = "muse" if payload is not None else "template"
        if payload is None:
            payload = template(facts)
            if reason:
                log.info("place explanation fallback to template: %s", reason)
        if cacheable:
            db.add(Explanation(facts_hash=key, model_version=facts.model_version, language=BASE_LANGUAGE,
                               profile=facts.profile, level=facts.level, source=source, payload=payload,
                               fallback_reason=reason))
            db.commit()
        return payload, source, False

    def _translation(self, db: Session, facts: PlaceFacts, base: dict, base_key: str, language: str, limiter,
                     user_key: str) -> tuple[dict | None, bool]:
        key = translation_key(base_key, language)
        row = db.scalar(select(Explanation).where(Explanation.facts_hash == key))
        if row:
            return (None if row.fallback_reason else row.payload), True
        if self.settings.muse_mock or self._limited(limiter, user_key):
            return None, False
        texts, reason = self._call_translate(source_texts(base), language, key, facts, base)
        if reason and (reason.startswith("api_error") or reason in RETRY_LATER):
            return None, False
        if reason:
            log.info("place translation to %s rejected: %s", language, reason)
        # A rejected translation is stored too, so the same text is not sent again.
        db.add(Explanation(facts_hash=key, model_version=facts.model_version, language=language,
                           profile=facts.profile, level=facts.level, source="muse" if texts else "template",
                           payload=texts or {}, fallback_reason=reason))
        db.commit()
        return texts, False

    def _ask(self, system_file: Path, user: dict, key: str, tag: str) -> tuple[dict | None, str | None]:
        messages = [{"role": "system", "content": system_file.read_text(encoding="utf-8")},
                    {"role": "user", "content": json.dumps(user, ensure_ascii=False)}]
        try:
            content, usage = self._post(messages)
        except Exception as exc:  # no retry loops (CLAUDE.md rule 23)
            self._log_usage(key, {}, f"{tag}_error:{type(exc).__name__}")
            return None, f"api_error:{type(exc).__name__}"
        if not content:
            reason = empty_reply_reason(usage)
            self._log_usage(key, usage, f"{tag}_{reason}")
            return None, reason
        try:
            payload = json.loads(_strip_fences(content))
        except (json.JSONDecodeError, TypeError):
            self._log_usage(key, usage, f"{tag}_invalid_json")
            return None, "invalid_json"
        self._log_usage(key, usage, f"{tag}_ok")
        return payload, None

    def _call_place(self, facts: PlaceFacts, catalog: dict, key: str) -> tuple[dict | None, str | None]:
        payload, reason = self._ask(PROMPT_FILE, {"facts": facts.public(), "catalog": catalog}, key, "place")
        if payload is None:
            return None, reason
        reason = verify(payload, facts, catalog)
        return (payload, None) if reason is None else (None, reason)

    def _call_translate(self, texts: dict, language: str, key: str, facts: PlaceFacts,
                        base: dict) -> tuple[dict | None, str | None]:
        payload, reason = self._ask(TRANSLATE_FILE, {"language": language, "texts": texts}, key, "translate")
        if payload is None:
            return None, reason
        reason = verify_translation(payload, base, facts)
        return (payload, None) if reason is None else (None, reason)
